create procedure archivar_entregados(lote int default 50000)
language plpgsql as $$
declare n int;
begin
  loop
    with viejos as (
      delete from envios where id in (select id from envios where estado = 'entregado' limit lote) returning *
    )
    insert into envios_archivo select * from viejos;
    get diagnostics n = row_count;
    exit when n = 0;
    raise notice 'archivados % envios', n;
    commit;
  end loop;
end $$;

