create function avisar() returns trigger language plpgsql as $$
begin
  raise notice '% % % (nivel %)', tg_when, tg_op, coalesce(new.id::text, '-'), tg_level;
  return new;
end $$;
create trigger t1_antes_sentencia before insert on prueba for each statement execute function avisar();
create trigger t2_antes_fila      before insert on prueba for each row       execute function avisar();
create trigger t3_despues_fila    after  insert on prueba for each row       execute function avisar();
create trigger t4_despues_sent    after  insert on prueba for each statement execute function avisar();
insert into prueba values (1, 'a'), (2, 'b');

create function limpiar() returns trigger language plpgsql as $$
begin
  new.nota := lower(trim(new.nota));         -- cambia la fila antes de guardarla
  if new.nota = '' then return null; end if;  -- NULL: esta fila se salta
  return new;
end $$;
create trigger limpiar before insert on prueba for each row execute function limpiar();
insert into prueba (id, nota) values (1, '  Frágil, no apilar '), (2, '   '), (3, 'REFRIGERADO');
select id, nota from prueba order by id;

create function cerrado_es_cerrado() returns trigger language plpgsql as $$
begin
  if old.estado = 'cerrado' and new.estado <> old.estado then
    raise exception 'un envio cerrado no se reabre (id %)', old.id;
  end if;
  return new;
end $$;
create trigger cerrado_es_cerrado before update of estado on prueba for each row execute function cerrado_es_cerrado();
update prueba set estado = 'cerrado' where id = 1;
update prueba set estado = 'abierto' where id = 1;

