create function auditar_fila() returns trigger language plpgsql as $$
begin
  insert into auditoria (tabla, paquete) values (tg_table_name, new.id);
  return null;
end $$;
create trigger auditar after insert on paquetes for each row execute function auditar_fila();

-- la alternativa: una sola vez por sentencia, con todas las filas nuevas
create function auditar_sentencia() returns trigger language plpgsql as $$
begin
  insert into auditoria (tabla, paquete) select tg_table_name, id from nuevos;
  return null;
end $$;
create trigger auditar after insert on paquetes referencing new table as nuevos
  for each statement execute function auditar_sentencia();

