create function tope_de_peso() returns trigger language plpgsql as $$
begin
  if new.peso_kg > 60 then raise exception 'peso fuera de rango en el paquete %: %', new.id, new.peso_kg; end if;
  return new;
end $$;
create trigger tope_de_peso before insert on paquetes for each row execute function tope_de_peso();
insert into paquetes select i, 'pendiente', case when i = 99999 then 99 else 1 + i % 50 end from generate_series(1, 100000) i;
